def problem_017(upper_bound: int = 1000, num2word: Dict[int, str] = num2word) -> int:
    """
    Solution using num2word mapping.
    """
    result = 0
    for n in range(1, upper_bound + 1):
        result += len(
            drop_spaces_or_hyphens(
                convert_num2word(n, num2word),
            ),
        )
    return result
